45	/* \brief the shape info of tensor;
46	 * \note this struct contains the shape info of tensor;
47	 * info:
48	 * shape: the tensor's shape
49	 * shapeDim: the tensor's shape dim
50	 * originalShape: the tensor's originalShape, for example, this tensor's NZ shape is
51	 * {32, 32, 16, 16}, but the original shape may be {32*16, 31*16}
52	 * dataFormat: tensor's format, ND or NZ;
53	 */
54	struct ShapeInfo {
55	public:
56	    __aicore__ inline ShapeInfo() {}
57	    __aicore__ inline ShapeInfo(
58	        const uint8_t inputShapeDim, const uint32_t inputShape[], const uint8_t inputOriginalShapeDim,
59	        const uint32_t inputOriginalShape[], const DataFormat inputFormat)
60	        : shapeDim(inputShapeDim), originalShapeDim(inputOriginalShapeDim), dataFormat(inputFormat)
61	    {
62	        ASCENDC_ASSERT((inputShapeDim <= K_MAX_SHAPE_DIM && inputOriginalShapeDim <= K_MAX_SHAPE_DIM), {
63	            KERNEL_LOG(
64	                KERNEL_ERROR, "inputShapeDim is %d, inputOriginalShapeDim is %d, which should be less than %d both",
65	                inputShapeDim, inputOriginalShapeDim, K_MAX_SHAPE_DIM);
66	        });
67	        for (int index = 0; index < shapeDim; ++index) {
68	            shape[index] = inputShape[index];
69	        }
70	        for (int index = 0; index < originalShapeDim; ++index) {
71	            originalShape[index] = inputOriginalShape[index];
72	        }
73	    }
74	    __aicore__ inline ShapeInfo(const uint8_t inputShapeDim, const uint32_t inputShape[], const DataFormat inputFormat)
75	        : shapeDim(inputShapeDim), originalShapeDim(inputShapeDim), dataFormat(inputFormat)
76	    {
77	        ASCENDC_ASSERT((inputShapeDim <= K_MAX_SHAPE_DIM), {
78	            KERNEL_LOG(
79	                KERNEL_ERROR, "inputShapeDim is %u, which should be less than %d", inputShapeDim, K_MAX_SHAPE_DIM);
80	        });
81	        for (int index = 0; index < shapeDim; ++index) {
82	            shape[index] = inputShape[index];
83	            originalShape[index] = inputShape[index];
84	        }
85	    }
86	
87	    __aicore__ inline ShapeInfo(const uint8_t inputShapeDim, const uint32_t inputShape[])
88	        : shapeDim(inputShapeDim), originalShapeDim(inputShapeDim), dataFormat(DataFormat::ND)
89	    {
90	        ASCENDC_ASSERT((inputShapeDim <= K_MAX_SHAPE_DIM), {
91	            KERNEL_LOG(
92	                KERNEL_ERROR, "inputShapeDim is %d, which should be less than %d", inputShapeDim, K_MAX_SHAPE_DIM);
93	        });
94	        for (int index = 0; index < shapeDim; ++index) {
95	            shape[index] = inputShape[index];
96	            originalShape[index] = inputShape[index];
97	        }
98	    }
99	    uint8_t shapeDim;
100	    uint8_t originalShapeDim;
101	    uint32_t shape[K_MAX_SHAPE_DIM];
102	    uint32_t originalShape[K_MAX_SHAPE_DIM];
103	    DataFormat dataFormat;
104	};
