122	    } else if constexpr (IsSameType<PrimType, int2b_t>::value) {
123	        ASCENDC_DEBUG_ASSERT(
124	            (this->address_.dataLen * INT2_FOUR > (offset / INT2_FOUR)),
125	            KERNEL_LOG_INTERNAL(
