131	        return reinterpret_cast<PrimType*>(this->address_.absAddr) + offset / INT2_FOUR;
132	    } else if constexpr (IsSameType<PrimType, uint1b_t>::value) {
133	        ASCENDC_DEBUG_ASSERT(
134	            (this->address_.dataLen * INT1_EIGHT > (offset / INT1_EIGHT)),
135	            KERNEL_LOG_INTERNAL(
136	                KERNEL_ERROR, "offset is %u, which can not be larger than data len %u", offset,
137	                static_cast<uint32_t>(this->address_.dataLen * INT1_EIGHT)));
138	        ASCENDC_DEBUG_ASSERT(
139	            (offset % INT1_EIGHT == 0),
140	            KERNEL_LOG_INTERNAL(KERNEL_ERROR, "The offset for uint1b_t GetPhyAddr should be multiples of 8."));
141	        return reinterpret_cast<PrimType*>(this->address_.absAddr) + offset / INT1_EIGHT;
142	#endif
143	#if defined(__NPU_ARCH__) && ((__NPU_ARCH__ == 3003) || (__NPU_ARCH__ == 3113))
144	    } else if constexpr (IsSameType<PrimType, uint2b_t>::value) {
145	        ASCENDC_DEBUG_ASSERT(
146	            (this->address_.dataLen * INT2_FOUR > (offset / INT2_FOUR)),
147	            KERNEL_LOG_INTERNAL(
148	                KERNEL_ERROR, "offset is %u, which can not be large than data len %u", offset,
149	                static_cast<uint32_t>(this->address_.dataLen * INT2_FOUR)));
150	        ASCENDC_DEBUG_ASSERT(
151	            (offset % INT2_FOUR == 0),
152	            KERNEL_LOG_INTERNAL(KERNEL_ERROR, "The offset for uint2b_t GetPhyAddr should be divisible by 4."));
153	        return reinterpret_cast<uint2b_t*>(this->address_.absAddr) + offset / INT2_FOUR;
154	#endif
