170	template <typename T>
171	__inout_pipe__(S) typename LocalTensor<T>::PrimType LocalTensor<T>::GetValue(const uint32_t offset) const
172	{
173	    if ASCEND_IS_AIC {
174	        if (GetPhyType(AscendC::TPosition(this->GetPosition())) == Hardware::UB) {
175	#if (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102)
176	            if constexpr (SupportType<PrimType, fp4x2_e2m1_t, fp4x2_e1m2_t>()) {
177	                PrimType ret;
178	                return ret;
179	            } else {
180	                return PrimType(0);
181	            }
182	#else
183	            return 0;
184	#endif
185	        }
186	    }
187	    if constexpr (IsSameType<PrimType, int4b_t>::value) {
188	        ASCENDC_DEBUG_ASSERT(
189	            (this->address_.dataLen * INT4_TWO > (offset / INT4_TWO)),
190	            KERNEL_LOG_INTERNAL(
191	                KERNEL_ERROR, "offset is %u, which can not be larger than data len %u", offset,
192	                static_cast<uint32_t>(this->address_.dataLen * INT4_TWO)));
193	
194	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
195	        uint8_t val = tmp.GetValue(offset / INT4_TWO);
196	        return static_cast<int4b_t>(val >> (4 * (offset % INT4_TWO)));
197	#if (__NPU_ARCH__ == 5102)
198	    } else if constexpr (IsSameType<PrimType, int2b_t>::value) {
199	        ASCENDC_DEBUG_ASSERT(
200	            (this->address_.dataLen * INT2_FOUR > (offset / INT2_FOUR)),
201	            KERNEL_LOG_INTERNAL(
202	                KERNEL_ERROR, "offset is %u, which can not be larger than data len %u", offset,
203	                static_cast<uint32_t>(this->address_.dataLen * INT2_FOUR)));
204	
205	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
206	        uint8_t val = tmp.GetValue(offset / INT2_FOUR);
207	        return static_cast<int2b_t>(val >> (2 * (offset % INT2_FOUR)));
208	    } else if constexpr (IsSameType<PrimType, uint1b_t>::value) {
209	        ASCENDC_DEBUG_ASSERT(
210	            (this->address_.dataLen * INT1_EIGHT > (offset / INT1_EIGHT)),
211	            KERNEL_LOG_INTERNAL(
212	                KERNEL_ERROR, "offset is %u, which can not be larger than data len %u", offset,
213	                static_cast<uint32_t>(this->address_.dataLen * INT1_EIGHT)));
214	
215	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
216	        uint8_t val = tmp.GetValue(offset / INT1_EIGHT);
217	        return static_cast<uint1b_t>(val >> (offset % INT1_EIGHT));
218	#endif
219	#if defined(__NPU_ARCH__) && ((__NPU_ARCH__ == 3003) || (__NPU_ARCH__ == 3113))
220	    } else if constexpr (IsSameType<PrimType, uint2b_t>::value) {
221	        ASCENDC_DEBUG_ASSERT(
222	            (this->address_.dataLen * INT2_FOUR > (offset / INT2_FOUR)),
223	            KERNEL_LOG_INTERNAL(
224	                KERNEL_ERROR, "offset is %u, which can not be large than data len %u", offset,
225	                static_cast<uint32_t>(this->address_.dataLen * INT2_FOUR)));
226	
227	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
228	        uint8_t val = tmp.GetValue(offset / INT2_FOUR);
229	        return static_cast<uint2b_t>(val >> (2 * (offset % INT2_FOUR)));
230	#endif
231	#if (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102)
232	    } else if constexpr (SupportType<PrimType, fp4x2_e2m1_t, fp4x2_e1m2_t>()) {
233	        ASCENDC_DEBUG_ASSERT(
234	            (this->address_.dataLen * ConstantsInternal::ASCENDC_B4_TWO > (offset / ConstantsInternal::ASCENDC_B4_TWO)),
235	            KERNEL_LOG_INTERNAL(
236	                KERNEL_ERROR, "offset is %u, which can not be larger than data len %u", offset,
237	                static_cast<uint32_t>(this->address_.dataLen * ConstantsInternal::ASCENDC_B4_TWO)));
238	
239	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
240	        uint8_t val = tmp.GetValue(offset / ConstantsInternal::ASCENDC_B4_TWO);
241	        PrimType ret;
242	        ret.val = static_cast<uint8_t>(
243	            (val >> (ConstantsInternal::ASCENDC_B4_BIT_NUM * (offset % ConstantsInternal::ASCENDC_B4_TWO))) & 0xf);
244	        return ret;
245	    } else if constexpr (SupportType<PrimType, complex32>()) {
246	        LocalTensor<uint32_t> tmp = this->ReinterpretCast<uint32_t>();
247	        uint32_t val = tmp.GetValue(offset);
248	        return *(reinterpret_cast<PrimType*>(&val));
249	    } else if constexpr (SupportType<PrimType, complex64>()) {
250	        LocalTensor<uint64_t> tmp = this->ReinterpretCast<uint64_t>();
251	        uint64_t val = tmp.GetValue(offset);
252	        return *(reinterpret_cast<PrimType*>(&val));
253	#endif
254	    } else {
255	        ASCENDC_DEBUG_ASSERT(
256	            (this->address_.dataLen > (offset * sizeof(PrimType))),
257	            KERNEL_LOG_INTERNAL(
258	                KERNEL_ERROR, "offset is %u, which can not be larger than data len %u", offset,
259	                static_cast<uint32_t>(this->address_.dataLen / sizeof(PrimType))));
260	        return *(GetPhyAddr(offset));
261	    }
262	}
