274	template <typename T>
275	template <typename U>
276	__aicore__ inline LocalTensor<U> LocalTensor<T>::ReinterpretCast() const
277	{
278	    LocalTensor<U> output;
279	    output.address_.logicPos = static_cast<uint8_t>(this->GetPosition());
280	    output.address_.bufferHandle = this->GetBufferHandle();
281	#if (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102)
282	    if constexpr (SupportType<PrimType, int4b_t, fp4x2_e2m1_t, fp4x2_e1m2_t>()) {
283	#else
284	    if constexpr (IsSameType<PrimType, int4b_t>::value) {
285	#endif
286	        output.address_.dataLen = this->GetSize() / INT4_TWO;
287	#if (__NPU_ARCH__ == 5102)
288	    } else if constexpr (IsSameType<PrimType, int2b_t>::value) {
289	        output.address_.dataLen = this->GetSize() / INT2_FOUR;
290	    } else if constexpr (IsSameType<PrimType, uint1b_t>::value) {
291	        output.address_.dataLen = this->GetSize() / INT1_EIGHT;
292	#endif
293	#if defined(__NPU_ARCH__) && ((__NPU_ARCH__ == 3003) || (__NPU_ARCH__ == 3113))
294	    } else if constexpr (IsSameType<PrimType, uint2b_t>::value) {
295	        output.address_.dataLen = this->GetSize() / INT2_FOUR;
296	#endif
297	    } else {
298	        output.address_.dataLen = this->GetSize() * sizeof(PrimType);
299	    }
300	    output.address_.bufferAddr = this->address_.bufferAddr;
301	    output.address_.absAddr = this->address_.absAddr;
302	    if constexpr (is_tensorTrait_v<T> && is_tensorTrait_v<U>) {
303	        output.GetTensorTrait().SetLayout(this->GetTensorTrait().GetLayout());
304	    }
305	    return output;
306	}
