308	template <typename T>
309	template <typename U>
310	__inout_pipe__(S) void LocalTensor<T>::SetValue(const uint32_t index, const U value) const
311	{
312	    if ASCEND_IS_AIC {
313	        if (GetPhyType(AscendC::TPosition(this->GetPosition())) == Hardware::UB) {
314	            return;
315	        }
316	    }
317	    if constexpr (IsSameType<PrimType, int4b_t>::value) {
318	        ASCENDC_DEBUG_ASSERT(
319	            (this->address_.dataLen * INT4_TWO > (index / INT4_TWO)),
320	            KERNEL_LOG_INTERNAL(
321	                KERNEL_ERROR, "index is %u, which can not be larger than data len %u", index,
322	                static_cast<uint32_t>(this->address_.dataLen * INT4_TWO)));
323	
324	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
325	        uint8_t shift = (index % INT4_TWO == 0) ? 0 : 4;
326	        uint32_t idx = index / INT4_TWO;
327	        uint8_t val = tmp.GetValue(idx) & (0xf << (INT4_BIT_NUM - shift));
328	        tmp.SetValue(idx, val + (value.storage << shift));
329	#if (__NPU_ARCH__ == 5102)
330	    } else if constexpr (IsSameType<PrimType, int2b_t>::value) {
331	        ASCENDC_DEBUG_ASSERT(
332	            (this->address_.dataLen * INT2_FOUR > (index / INT2_FOUR)),
333	            KERNEL_LOG_INTERNAL(
334	                KERNEL_ERROR, "index is %u, which can not be larger than data len %u", index,
335	                static_cast<uint32_t>(this->address_.dataLen * INT2_FOUR)));
336	
337	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
338	        uint8_t shift = (index % INT2_FOUR) * 2;
339	        uint32_t idx = index / INT2_FOUR;
340	        uint8_t mask = (0x3) << shift;
341	        uint8_t maskedVal = tmp.GetValue(idx) & (~mask);
342	        tmp.SetValue(idx, maskedVal + (value.storage << shift));
343	    } else if constexpr (IsSameType<PrimType, uint1b_t>::value) {
344	        ASCENDC_DEBUG_ASSERT(
345	            (this->address_.dataLen * INT1_EIGHT > (index / INT1_EIGHT)),
346	            KERNEL_LOG_INTERNAL(
347	                KERNEL_ERROR, "index is %u, which can not be larger than data len %u", index,
348	                static_cast<uint32_t>(this->address_.dataLen * INT1_EIGHT)));
349	
350	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
351	        uint8_t shift = index % INT1_EIGHT;
352	        uint32_t idx = index / INT1_EIGHT;
353	        uint8_t mask = (0x1) << shift;
354	        uint8_t maskedVal = tmp.GetValue(idx) & (~mask);
355	        tmp.SetValue(idx, maskedVal + (value.storage << shift));
356	#endif
357	#if defined(__NPU_ARCH__) && ((__NPU_ARCH__ == 3003) || (__NPU_ARCH__ == 3113))
358	    } else if constexpr (IsSameType<PrimType, uint2b_t>::value) {
359	        ASCENDC_DEBUG_ASSERT(
360	            (this->address_.dataLen * INT2_FOUR > (index / INT2_FOUR)),
361	            KERNEL_LOG_INTERNAL(
362	                KERNEL_ERROR, "index is %u, which can not be large than data len %u", index,
363	                static_cast<uint32_t>(this->address_.dataLen * INT2_FOUR)));
364	
365	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
366	        uint32_t idx = index / INT2_FOUR;
367	        uint8_t shift = 2 * (index % INT2_FOUR);
368	        uint8_t val;
369	        if (index % INT2_FOUR == 0) {
370	            val = tmp.GetValue(idx) & 0xFC;
371	        } else if (index % INT2_FOUR == 1) {
372	            val = tmp.GetValue(idx) & 0xF3;
373	        } else if (index % INT2_FOUR == 2) {
374	            val = tmp.GetValue(idx) & 0xCF;
375	        } else {
376	            val = tmp.GetValue(idx) & 0x3F;
377	        }
378	        tmp.SetValue(idx, val + (value.storage << shift));
379	#endif
380	#if (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102)
381	    } else if constexpr (SupportType<PrimType, fp4x2_e2m1_t, fp4x2_e1m2_t>()) {
382	        ASCENDC_DEBUG_ASSERT(
383	            (this->address_.dataLen * ConstantsInternal::ASCENDC_B4_TWO > (index / ConstantsInternal::ASCENDC_B4_TWO)),
384	            KERNEL_LOG_INTERNAL(
385	                KERNEL_ERROR, "index is %u, which can not be larger than data len %u", index,
386	                static_cast<uint32_t>(this->address_.dataLen * ConstantsInternal::ASCENDC_B4_TWO)));
387	
388	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
389	        uint8_t shift = (index % ConstantsInternal::ASCENDC_B4_TWO == 0) ? 0 : ConstantsInternal::ASCENDC_B4_BIT_NUM;
390	        uint32_t idx = index / ConstantsInternal::ASCENDC_B4_TWO;
391	        uint8_t val = tmp.GetValue(idx) & (0xf << (ConstantsInternal::ASCENDC_B4_BIT_NUM - shift));
392	        tmp.SetValue(idx, val + (value << shift));
393	#endif
394	    } else {
395	        ASCENDC_DEBUG_ASSERT(
396	            (this->address_.dataLen > (index * sizeof(PrimType))),
397	            KERNEL_LOG_INTERNAL(
398	                KERNEL_ERROR, "index is %u, which can not be larger than data len %u", index,
399	                static_cast<uint32_t>(this->address_.dataLen / sizeof(PrimType))));
400	        *(GetPhyAddr(index)) = PrimType(value);
401	    }
402	}
