444	                static_cast<uint32_t>(this->address_.dataLen / sizeof(PrimType))));
445	    }
446	
447	    LocalTensor result = *this;
448	#if (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102)
