495	{
496	    static constexpr uint16_t all16BitsOne = 0xFFFF;
497	    static constexpr uint32_t all32BitsOne = 0xFFFFFFFF;
498	    static_assert(SupportType<T, complex32, complex64>(), "Unsupported complex type.");
499	    std::string str = "";
