502	            str += std::to_string(val.real.ToFloat()) + "+" + std::to_string(val.imag.ToFloat()) + "j ";
503	        } else {
504	            str += std::to_string(val.real.ToFloat()) + std::to_string(val.imag.ToFloat()) + "j ";
505	        }
506	    } else {
507	        if (val.imag > 0 || !(*(reinterpret_cast<const uint32_t*>(&val.imag)) & all32BitsOne)) {
508	            str += std::to_string(val.real) + "+" + std::to_string(val.imag) + "j ";
509	        } else {
510	            str += std::to_string(val.real) + std::to_string(val.imag) + "j ";
511	        }
512	    }
513	    return str;
514	}
