759	__aicore__ inline __inout_pipe__(S)
760	    typename LocalTensor<T>::PrimType LocalTensor<T>::GetValue(const uint32_t index) const
761	{
762	    if ASCEND_IS_AIC {
763	        if (GetPhyType(AscendC::TPosition(this->GetPosition())) == Hardware::UB) {
764	#if (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102)
765	            if constexpr (SupportType<PrimType, fp4x2_e2m1_t, fp4x2_e1m2_t, fp8_e4m3fn_t, fp8_e5m2_t, hifloat8_t>()) {
766	                PrimType ret;
