770	            }
771	#else
772	            return PrimType(0);
773	#endif
774	        }
775	    }
776	    if constexpr (IsSameType<PrimType, int4b_t>::value) {
777	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
778	        uint8_t val = tmp.GetValue(index / INT4_TWO);
779	        return static_cast<int4b_t>(val >> (INT4_BIT_NUM * (index % INT4_TWO)));
780	#if (__NPU_ARCH__ == 5102)
781	    } else if constexpr (IsSameType<PrimType, int2b_t>::value) {
782	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
783	        uint8_t val = tmp.GetValue(index / INT2_FOUR);
784	        return static_cast<int2b_t>(val >> (INT2_BIT_NUM * (index % INT2_FOUR)));
785	    } else if constexpr (IsSameType<PrimType, uint1b_t>::value) {
786	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
787	        uint8_t val = tmp.GetValue(index / INT1_EIGHT);
788	        return static_cast<uint1b_t>(val >> (INT1_BIT_NUM * (index % INT1_EIGHT)));
789	#endif
790	#if defined(__NPU_ARCH__) && ((__NPU_ARCH__ == 3003) || (__NPU_ARCH__ == 3113))
791	    } else if constexpr (IsSameType<T, uint2b_t>::value) {
792	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
793	        uint8_t val = tmp.GetValue(index / INT2_FOUR);
794	        return static_cast<uint2b_t>(val >> (INT2_BIT_NUM * (index % INT2_FOUR)));
795	#endif
796	#if (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102)
797	    } else if constexpr (SupportType<PrimType, complex32>()) {
798	        LocalTensor<uint32_t> tmp = this->ReinterpretCast<uint32_t>();
799	        uint32_t val = tmp.GetValue(index);
800	        return *(reinterpret_cast<PrimType*>(&val));
801	    } else if constexpr (SupportType<PrimType, complex64>()) {
802	        LocalTensor<uint64_t> tmp = this->ReinterpretCast<uint64_t>();
803	        uint64_t val = tmp.GetValue(index);
804	        return *(reinterpret_cast<PrimType*>(&val));
805	#endif
806	    } else {
807	        return *(reinterpret_cast<__ubuf__ PrimType*>(GetPhyAddr(index)));
808	    }
809	}
