818	template <typename U>
819	__aicore__ inline __sync_alias__ LocalTensor<U> LocalTensor<T>::ReinterpretCast() const
820	{
821	    LocalTensor<U> output;
822	    output.address_.logicPos = static_cast<uint8_t>(this->GetPosition());
823	    output.address_.bufferHandle = this->GetBufferHandle();
824	    if constexpr (IsHalfByteDataType<PrimType>()) {
825	        output.address_.dataLen = this->GetSize() / INT4_TWO;
826	#if (__NPU_ARCH__ == 5102)
827	    } else if constexpr (IsSameType<PrimType, int2b_t>::value) {
828	        output.address_.dataLen = this->GetSize() / INT2_FOUR;
829	    } else if constexpr (IsSameType<PrimType, uint1b_t>::value) {
830	        output.address_.dataLen = this->GetSize() / INT1_EIGHT;
831	#endif
832	#if defined(__NPU_ARCH__) && ((__NPU_ARCH__ == 3003) || (__NPU_ARCH__ == 3113))
833	    } else if constexpr (IsSameType<T, uint2b_t>::value) {
834	        output.address_.dataLen = this->GetSize() / INT2_FOUR;
835	#endif
836	    } else {
837	        output.address_.dataLen = this->GetSize() * sizeof(PrimType);
838	    }
839	    output.address_.bufferAddr = this->address_.bufferAddr;
840	    if constexpr (is_tensorTrait_v<T> && is_tensorTrait_v<U>) {
841	        output.SetTensorTrait(this->GetTensorTrait());
842	    }
843	    return output;
