846	template <typename T>
847	template <typename U>
848	__aicore__ inline __inout_pipe__(S) void LocalTensor<T>::SetValue(const uint32_t index, const U value) const
849	{
850	    if ASCEND_IS_AIC {
851	        if (GetPhyType(AscendC::TPosition(this->GetPosition())) == Hardware::UB) {
852	            return;
853	        }
854	    }
855	    if constexpr (IsSameType<PrimType, int4b_t>::value) {
856	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
857	        uint8_t mask = (index % INT4_TWO == 0) ? 0xf0 : 0xf;
858	        uint32_t idx = index / INT4_TWO;
859	        uint8_t val = tmp.GetValue(idx) & mask;
860	        uint8_t shift = (index % INT4_TWO == 0) ? 0 : INT4_BIT_NUM;
861	        tmp.SetValue(idx, val + (value.storage << shift));
862	#if (__NPU_ARCH__ == 5102)
863	    } else if constexpr (IsSameType<PrimType, int2b_t>::value) {
864	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
865	        uint8_t shift = (index % INT2_FOUR) * 2;
866	        uint32_t idx = index / INT2_FOUR;
867	        uint8_t mask = (0x3) << shift;
868	        uint8_t maskedVal = tmp.GetValue(idx) & (~mask);
869	        tmp.SetValue(idx, maskedVal + (value.storage << shift));
870	    } else if constexpr (IsSameType<PrimType, uint1b_t>::value) {
871	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
872	        uint8_t shift = index % INT1_EIGHT;
873	        uint32_t idx = index / INT1_EIGHT;
874	        uint8_t mask = (0x1) << shift;
875	        uint8_t maskedVal = tmp.GetValue(idx) & (~mask);
876	        tmp.SetValue(idx, maskedVal + (value.storage << shift));
877	#endif
878	#if defined(__NPU_ARCH__) && ((__NPU_ARCH__ == 3003) || (__NPU_ARCH__ == 3113))
879	    } else if constexpr (IsSameType<PrimType, uint2b_t>::value) {
880	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
881	        uint32_t idx = index / INT2_FOUR;
882	        uint8_t shift = 2 * (index % INT2_FOUR);
883	        uint8_t val;
884	        if (index % INT2_FOUR == 0) {
885	            val = tmp.GetValue(idx) & 0xFC;
886	        } else if (index % INT2_FOUR == 1) {
887	            val = tmp.GetValue(idx) & 0xF3;
888	        } else if (index % INT2_FOUR == 2) {
889	            val = tmp.GetValue(idx) & 0xCF;
890	        } else {
891	            val = tmp.GetValue(idx) & 0x3F;
892	        }
893	        tmp.SetValue(idx, val + (value.storage << shift));
894	#endif
895	#if (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102)
896	    } else if constexpr (SupportType<PrimType, fp4x2_e2m1_t, fp4x2_e1m2_t>()) {
897	        LocalTensor<uint8_t> tmp = this->ReinterpretCast<uint8_t>();
898	        uint8_t mask = (index % ConstantsInternal::ASCENDC_B4_TWO == 0) ? 0xf0 : 0xf;
899	        uint32_t idx = index / ConstantsInternal::ASCENDC_B4_TWO;
900	        uint8_t val = tmp.GetValue(idx) & mask;
901	        uint8_t shift = (index % ConstantsInternal::ASCENDC_B4_TWO == 0) ? 0 : ConstantsInternal::ASCENDC_B4_BIT_NUM;
902	        tmp.SetValue(idx, val + (value << shift));
903	    } else if constexpr (SupportType<PrimType, complex32, complex64>()) {
904	        __ubuf__ PrimType* tmpAddr =
905	            reinterpret_cast<__ubuf__ T*>(static_cast<uint64_t>(this->address_.bufferAddr)) + index;
906	        PrimType valueAux(value);
907	        *(reinterpret_cast<__ubuf__ typename PrimType::EleType*>(tmpAddr)) = valueAux.real;
908	        *(reinterpret_cast<__ubuf__ typename PrimType::EleType*>(tmpAddr) + 1) = valueAux.imag;
909	#endif
910	    } else {
911	        *(reinterpret_cast<__ubuf__ PrimType*>(static_cast<uint64_t>(this->address_.bufferAddr)) + index) =
912	            static_cast<PrimType>(value);
913	    }
914	}
