1045	template <typename T>
1046	template <typename U>
1047	__aicore__ inline void LocalTensor<T>::CreateTensor(AscendC::TPosition pos, uint32_t addr, uint32_t tileSize)
1048	{
1049	#if ASCENDC_CPU_DEBUG
1050	    ASCENDC_DEBUG_ASSERT(
1051	        (pos != AscendC::TPosition::GM) && (pos != AscendC::TPosition::MAX),
1052	        KERNEL_LOG_INTERNAL(KERNEL_ERROR, "position input should not be GM or MAX"));
1053	    AscendC::Hardware hardPos = ConstDefiner::Instance().positionHardMap.at(pos);
1054	    uint32_t maxLen = ConstDefiner::Instance().bufferInitLen.at(hardPos);
1055	    ASCENDC_DEBUG_ASSERT(
1056	        (addr % ONE_BLK_SIZE == 0),
1057	        KERNEL_LOG_INTERNAL(KERNEL_ERROR, "addr input is %u, which should be 32 bytes align", addr));
1058	    if constexpr (IsHalfByteDataType<PrimType>()) {
1059	        ASCENDC_DEBUG_ASSERT(
1060	            ((tileSize > 0) && ((tileSize % INT4_TWO) == 0) && (tileSize / INT4_TWO) <= maxLen),
1061	            KERNEL_LOG_INTERNAL(
1062	                KERNEL_ERROR, "tensor size input is %u, which should be even number in range (0, %u]", tileSize,
1063	                maxLen * INT4_TWO));
1064	    } else {
1065	        ASCENDC_DEBUG_ASSERT(
1066	            ((tileSize > 0) && (tileSize * sizeof(U)) <= maxLen),
1067	            KERNEL_LOG_INTERNAL(
1068	                KERNEL_ERROR, "tensor size input is %u, which should be in range (0, %u]", tileSize,
1069	                maxLen / sizeof(U)));
1070	    }
1071	    uint32_t tensorLength = tileSize * SizeOfBits<U>::value / SizeOfBits<uint8_t>::value;
1072	    ASCENDC_DEBUG_ASSERT(
1073	        (tensorLength % ONE_BLK_SIZE == 0),
1074	        KERNEL_LOG_INTERNAL(KERNEL_ERROR, "tensor length is %u bytes, which should be 32 bytes align", tensorLength));
1075	    ASCENDC_DEBUG_ASSERT(
1076	        ((addr >= 0) && ((addr + tensorLength) <= maxLen)),
1077	        KERNEL_LOG_INTERNAL(
1078	            KERNEL_ERROR, "addr input is %u, tensor length is %u bytes, which exceeds max len %u bytes", addr,
1079	            tensorLength, maxLen));
1080	    this->address_.bufferHandle = nullptr;
1081	    this->address_.absAddr = GetBaseAddrCpu(static_cast<int8_t>(pos)) + addr;
1082	#endif
1083	    this->address_.dataLen = SizeOfBits<U>::value * tileSize / SizeOfBits<uint8_t>::value;
1084	    this->address_.bufferAddr = addr;
1085	    this->address_.logicPos = static_cast<uint8_t>(pos);
1086	}
