1466	            reinterpret_cast<__gm__ uint8_t*>(ExtractL2CacheGmAddr(this->address_)) + offset / INT1_EIGHT;
1467	#ifdef __ASCENDC_SUPER_KERNEL_ENABLE_GM_GET_SET_VALUE_DCCI__
1468	        DcciCacheLine(AlignPtr<uint8_t>(addr));
1469	#endif
1470	        return static_cast<T>((*addr) >> (INT1_BIT_NUM * (offset % INT1_EIGHT)));
1471	#endif
1472	    } else {
1473	        __gm__ T* addr = ExtractL2CacheGmAddr(this->address_ + offset);
1474	#ifdef __ASCENDC_SUPER_KERNEL_ENABLE_GM_GET_SET_VALUE_DCCI__
1475	        DcciCacheLine(AlignPtr<T>(addr));
1476	#endif
1477	        if constexpr (SupportType<PrimType, complex32, complex64>()) {
1478	            return T(addr->real, addr->imag);
1479	        } else {
1480	            return *addr;
1481	        }
1482	    }
1483	#else
1484	    if constexpr (IsHalfByteDataType<PrimType>()) {
1485	        __gm__ uint8_t* addr = reinterpret_cast<__gm__ uint8_t*>(this->oriAddress_) + offset / INT4_TWO;
1486	#ifdef __ASCENDC_SUPER_KERNEL_ENABLE_GM_GET_SET_VALUE_DCCI__
1487	        DcciCacheLine(AlignPtr<uint8_t>(addr));
1488	#endif
1489	        return static_cast<PrimType>((*addr) >> (INT4_BIT_NUM * (offset % INT4_TWO)));
1490	#if defined(__NPU_ARCH__) && ((__NPU_ARCH__ == 3003) || (__NPU_ARCH__ == 3113))
1491	    } else if constexpr (IsSameType<PrimType, uint2b_t>::value) {
1492	        __gm__ uint8_t* addr = reinterpret_cast<__gm__ uint8_t*>(this->oriAddress_) + offset / INT2_FOUR;
1493	        return static_cast<T>((*addr) >> (INT2_BIT_NUM * (offset % INT2_FOUR)));
1494	#endif
1495	    } else {
1496	#ifdef __ASCENDC_SUPER_KERNEL_ENABLE_GM_GET_SET_VALUE_DCCI__
1497	        DcciCacheLine(AlignPtr<PrimType>(this->oriAddress_ + offset));
1498	#endif
1499	        return this->oriAddress_[offset];
1500	    }
1501	#endif
1502	}
1503	
1504	#ifdef __ASCENDC_SUPER_KERNEL_ENABLE_GM_GET_SET_VALUE_DCCI__
1505	template <typename T>
1506	__aicore__ inline __inout_pipe__(S) __gm__
1507	typename GlobalTensor<T>::PrimType& GlobalTensor<T>::operator()(const uint64_t offset)
1508	{
1509	#if (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102)
1510	    __gm__ PrimType* addr = ExtractL2CacheGmAddr(this->address_);
1511	    DcciReadCache(addr + offset);
1512	    return addr[offset];
1513	#else
1514	    DcciReadCache(this->oriAddress_ + offset);
1515	    return this->oriAddress_[offset];
1516	#endif
1517	}
1518	#endif
