1522	typename GlobalTensor<T>::PrimType& GlobalTensor<T>::operator()(const uint64_t offset) const
1523	{
1524	#if (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102)
1525	    __gm__ PrimType* addr = ExtractL2CacheGmAddr(this->address_);
1526	#ifdef __ASCENDC_SUPER_KERNEL_ENABLE_GM_GET_SET_VALUE_DCCI__
1527	    DcciCacheLine(AlignPtr<PrimType>(addr + offset));
1528	#endif
1529	    return addr[offset];
1530	#else
1531	#ifdef __ASCENDC_SUPER_KERNEL_ENABLE_GM_GET_SET_VALUE_DCCI__
