1538	template <typename T>
1539	__aicore__ inline void GlobalTensor<T>::SetValue(const uint64_t offset, typename GlobalTensor<T>::PrimType value)
1540	{
1541	#if (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102)
1542	    if constexpr (SupportType<PrimType, int4b_t, fp4x2_e2m1_t, fp4x2_e1m2_t>()) {
1543	        __gm__ uint8_t* addr =
1544	            reinterpret_cast<__gm__ uint8_t*>(ExtractL2CacheGmAddr(this->address_)) + offset / INT4_TWO;
1545	        uint8_t mask = (offset % INT4_TWO == 0) ? 0xf0 : 0xf;
1546	
1547	#ifdef __ASCENDC_SUPER_KERNEL_ENABLE_GM_GET_SET_VALUE_DCCI__
1548	        DcciWriteCache(addr);
1549	#endif
1550	        uint8_t val = (*addr) & mask;
1551	        uint8_t shift = (offset % INT4_TWO == 0) ? 0 : INT4_BIT_NUM;
1552	        *addr = val + (value.storage << shift);
1553	#if (__NPU_ARCH__ == 5102)
1554	    } else if constexpr (SupportType<PrimType, int2b_t>()) {
1555	        __gm__ uint8_t* addr =
1556	            reinterpret_cast<__gm__ uint8_t*>(ExtractL2CacheGmAddr(this->address_)) + offset / INT2_FOUR;
1557	
1558	#ifdef __ASCENDC_SUPER_KERNEL_ENABLE_GM_GET_SET_VALUE_DCCI__
1559	        DcciWriteCache(addr);
1560	#endif
1561	        uint8_t shift = (offset % INT2_FOUR) * 2;
1562	        uint8_t mask = (0x3) << shift;
1563	        uint8_t maskedVal = (*addr) & (~mask);
1564	        *addr = maskedVal + (value.storage << shift);
1565	    } else if constexpr (SupportType<PrimType, uint1b_t>()) {
1566	        __gm__ uint8_t* addr =
1567	            reinterpret_cast<__gm__ uint8_t*>(ExtractL2CacheGmAddr(this->address_)) + offset / INT1_EIGHT;
1568	
1569	#ifdef __ASCENDC_SUPER_KERNEL_ENABLE_GM_GET_SET_VALUE_DCCI__
1570	        DcciWriteCache(addr);
1571	#endif
1572	        uint8_t shift = offset % INT1_EIGHT;
1573	        uint8_t mask = (0x1) << shift;
1574	        uint8_t maskedVal = (*addr) & (~mask);
1575	        *addr = maskedVal + (value.storage << shift);
1576	#endif
1577	    } else {
1578	        __gm__ PrimType* addr = ExtractL2CacheGmAddr(this->address_ + offset);
1579	#ifdef __ASCENDC_SUPER_KERNEL_ENABLE_GM_GET_SET_VALUE_DCCI__
1580	        DcciWriteCache(addr);
1581	#endif
1582	        *addr = value;
1583	    }
1584	#else
1585	    if constexpr (IsHalfByteDataType<PrimType>()) {
1586	        __gm__ uint8_t* addr = reinterpret_cast<__gm__ uint8_t*>(this->oriAddress_) + offset / INT4_TWO;
1587	        uint8_t mask = (offset % INT4_TWO == 0) ? 0xf0 : 0xf;
1588	
1589	#ifdef __ASCENDC_SUPER_KERNEL_ENABLE_GM_GET_SET_VALUE_DCCI__
1590	        DcciWriteCache(addr);
1591	#endif
1592	        uint8_t val = (*addr) & mask;
1593	        uint8_t shift = (offset % INT4_TWO == 0) ? 0 : INT4_BIT_NUM;
1594	        *addr = val + (value.storage << shift);
1595	#if defined(__NPU_ARCH__) && ((__NPU_ARCH__ == 3003) || (__NPU_ARCH__ == 3113))
1596	    } else if constexpr (IsSameType<T, uint2b_t>::value) {
1597	        __gm__ uint8_t* addr = reinterpret_cast<__gm__ uint8_t*>(this->oriAddress_) + offset / INT2_FOUR;
1598	        // example: origin data is 0b10110110, need to set higheset 2bit to 0b11, offset is 3
1599	        // mask is 0xCF(0b00111111), after mask operation, origin data becomes 0b00110110
1600	        // shift is 6, findal val is 0b00110110 + 0b11 << 6 = 0b11110110
1601	        uint8_t mask = 0;
1602	        if (offset % INT2_FOUR == 0) {
1603	            mask = 0xFC;
1604	        } else if (offset % INT2_FOUR == 1) {
1605	            mask = 0xF3;
1606	        } else if (offset % INT2_FOUR == 2) {
1607	            mask = 0xCF;
1608	        } else {
1609	            mask = 0x3F;
1610	        }
1611	
1612	        uint8_t val = (*addr) & mask;
1613	        uint8_t shift = 2 * (offset % INT2_FOUR);
1614	        *addr = val + (value.storage << shift);
1615	#endif
1616	    } else {
1617	#ifdef __ASCENDC_SUPER_KERNEL_ENABLE_GM_GET_SET_VALUE_DCCI__
1618	        DcciWriteCache(this->oriAddress_ + offset);
1619	#endif
1620	        this->oriAddress_[offset] = value;
1621	    }
1622	#endif
1623	}
