{
    this->cacheMode_ = mode;
#if (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102)
    this->address_ = L2CacheAlter<PrimType, rwMode>(this->address_, mode);
#else
    if (mode == CacheMode::CACHE_MODE_NORMAL) {
        this->address_ = this->oriAddress_;
